static int isl29020_probe ( struct i2c_client * client , const struct i2c_device_id * id ) { int res ; res = als_set_default_config ( client ) ; res = sysfs_create_group ( & client -> dev . kobj , & m_als_gr ) ; if ( res ) { dev_err ( & client -> dev , "isl29020: device create file failed\n" ) ; return res ; } dev_info ( & client -> dev , "%s isl29020: ALS chip found\n" , client -> name ) ; als_set_power_state ( client , 0 ) ; pm_runtime_enable ( & client -> dev ) ; return res ; } 